package com.isc.useridentity.controller;
import com.isc.useridentity.api.ApiDtos; import com.isc.useridentity.domain.AssuranceLevel; import com.isc.useridentity.service.AuthenticationService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/authentication-contexts") @RequiredArgsConstructor public class InternalAuthenticationController { private final AuthenticationService s; @PostMapping("/{id}/verify") public ApiDtos.AuthenticationContext verify(@PathVariable String id,@RequestParam(required=false) String userId,@RequestParam(required=false) String clientId,@RequestParam(defaultValue="IAL_2") AssuranceLevel requiredAssuranceLevel){return s.verifyForToken(id,userId,clientId,requiredAssuranceLevel);} }
